<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Configuration;use App\Application\Audit\AuditWriter;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class RegulatoryConfigurationController{
public function show(Request$r,string$code){$d=$r->validate(['jurisdiction'=>'nullable|string|size:2']);$row=DB::table('regulatory_reference_sets')->where(['jurisdiction'=>$d['jurisdiction']??'CM','code'=>$code,'status'=>'ACTIVE'])->first();abort_unless($row,404);return response()->json(['data'=>['code'=>$row->code,'jurisdiction'=>$row->jurisdiction,'version'=>$row->version,'entries'=>json_decode($row->entries,true)]]);}
public function store(Request$r,AuditWriter$audit){$d=$r->validate(['jurisdiction'=>'required|string|size:2','code'=>'required|string|max:80','effective_from'=>'required|date','effective_until'=>'nullable|date|after:effective_from','entries'=>'required|array|min:1']);$version=(DB::table('regulatory_reference_sets')->where(['jurisdiction'=>$d['jurisdiction'],'code'=>$d['code']])->max('version')??0)+1;$canonical=json_encode($d['entries'],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);$id=(string)Str::uuid();DB::table('regulatory_reference_sets')->insert([...$d,'id'=>$id,'version'=>$version,'status'=>'DRAFT','entries'=>$canonical,'content_hash'=>hash('sha256',$canonical),'created_at'=>now(),'updated_at'=>now()]);$audit->record('regulatory_reference.created','regulatory_reference_set',$id,['code'=>$d['code'],'version'=>$version]);return response()->json(['data'=>['id'=>$id,'version'=>$version,'status'=>'DRAFT']],201);}
public function approve(Request$r,string$set,AuditWriter$audit){$d=$r->validate(['reason'=>'required|string|min:20|max:2000']);$row=DB::table('regulatory_reference_sets')->where('id',$set)->where('status','DRAFT')->first();abort_unless($row,409);DB::transaction(function()use($row,$set,$r,$audit){DB::table('regulatory_reference_sets')->where(['jurisdiction'=>$row->jurisdiction,'code'=>$row->code,'status'=>'ACTIVE'])->update(['status'=>'RETIRED','effective_until'=>now()->toDateString(),'updated_at'=>now()]);DB::table('regulatory_reference_sets')->where('id',$set)->update(['status'=>'ACTIVE','approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);$audit->record('regulatory_reference.approved','regulatory_reference_set',$set,['code'=>$row->code,'version'=>$row->version]);});return response()->json(['data'=>['id'=>$set,'status'=>'ACTIVE']]);}}
